/**
 * Render a Hugeicons stroke-rounded icon inline.
 */
function hi(string $name, int $size = 18, string $class = ''): string {
    if (!isset(HUGEICONS[$name])) return '';
    $classAttr = $class !== '' ? ' class="' . htmlspecialchars($class) . '"' : '';
    return '<svg' . $classAttr . ' width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">' . HUGEICONS[$name] . '</svg>';
}
